def main():
    cat=json.load((ROOT/'inputs/candidate_catalog.json').open()); example=cat['candidates'][0]
    props={}
    numeric={'demand_value','net_fare_rub','available_aircraft'}
    for k,v in example.items():
        if k in numeric:props[k]={'type':['number','null'],'minimum':0}
        elif k=='selected_for_deepening':props[k]={'type':'boolean'}
        elif k=='political_change_date':props[k]={'type':'null','description':'No political date forecasts in this research'}
        elif k=='program_manifest':props[k]={'anyOf':[{'type':'null'},{'$ref':'#/$defs/program'}]}
        else:props[k]={'type':'string'}
    props['candidate_id']={'type':'string','pattern':'^C[0-9]{2}$'}
    props['evaluation_status']={'enum':['NOT_EVALUATED','PARTIAL_GEOMETRY_ONLY','CONDITIONALLY_EVALUATED','FAILED_CONSTRAINT','HELD_DATA','RETIRED_WITH_REASON']}
    for k in ['demand_status','net_fare_status','frequency_status','resource_status','value_type']:
        props[k]={'enum':['OBSERVED','DERIVED','MODEL_ESTIMATE','SCENARIO','UNKNOWN']}
    measure={'type':'object','required':['value','unit','period','value_type','source_ids','missing_reason'],'properties':{'value':{'type':['number','null']},'unit':{'type':'string'},'period':{'type':'string'},'value_type':{'enum':['OBSERVED','DERIVED','MODEL_ESTIMATE','SCENARIO','UNKNOWN']},'source_ids':{'type':'array','items':{'type':'string'}},'missing_reason':{'type':['string','null']}},'additionalProperties':False,'allOf':[{'if':{'properties':{'value_type':{'const':'UNKNOWN'}}},'then':{'properties':{'value':{'type':'null'},'missing_reason':{'type':'string','minLength':1}}}}]}
    program={'type':'object','required':['period','baseline_id','data_manifest_sha256','evaluator_version','scenario_version','resource_budget_id','operating_legs','products','local_module_ids','switching_costs','hypothesis_family_id'],'properties':{'period':{'type':'object','required':['start','end'],'properties':{'start':{'type':'string','format':'date'},'end':{'type':'string','format':'date'}},'additionalProperties':False},'baseline_id':{'type':'string'},'data_manifest_sha256':{'type':'string','pattern':'^[0-9a-f]{64}$'},'evaluator_version':{'type':'string'},'scenario_version':{'type':'string'},'resource_budget_id':{'type':'string'},'hypothesis_family_id':{'type':'string'},'local_module_ids':{'type':'array','items':{'type':'string'}},'switching_costs':{'type':'array','items':{'$ref':'#/$defs/measure'}},'operating_legs':{'type':'array','items':{'$ref':'#/$defs/leg'}},'products':{'type':'array','items':{'$ref':'#/$defs/product'}}},'additionalProperties':False}
    leg={'type':'object','required':['leg_id','origin_airport_id','destination_airport_id','departure_utc','arrival_utc','departure_timezone','arrival_timezone','aircraft_resource_id','leg_role','seats','source_snapshot_ids'],'properties':{'leg_id':{'type':'string'},'origin_airport_id':{'type':'string'},'destination_airport_id':{'type':'string'},'departure_utc':{'type':'string','format':'date-time'},'arrival_utc':{'type':'string','format':'date-time'},'departure_timezone':{'type':'string'},'arrival_timezone':{'type':'string'},'aircraft_resource_id':{'type':'string'},'leg_role':{'enum':['commercial','positioning','reserve_recovery']},'seats':{'$ref':'#/$defs/measure'},'source_snapshot_ids':{'type':'array','items':{'type':'string'}}},'additionalProperties':False}
    product={'type':'object','required':['product_id','origin_airport_id','destination_airport_id','outbound_leg_ids','return_leg_ids','purpose','stay_nights','protection','net_revenue','demand_input_id','own_migration_input_id'],'properties':{'product_id':{'type':'string'},'origin_airport_id':{'type':'string'},'destination_airport_id':{'type':'string'},'outbound_leg_ids':{'type':'array','minItems':1,'items':{'type':'string'}},'return_leg_ids':{'type':'array','items':{'type':'string'}},'purpose':{'type':'string'},'stay_nights':{'type':['integer','null'],'minimum':0},'protection':{'enum':['contract_verified','scenario_only','self_connect','not_applicable']},'net_revenue':{'$ref':'#/$defs/measure'},'demand_input_id':{'type':'string'},'own_migration_input_id':{'type':'string'}},'additionalProperties':False}
    schema={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'Red Wings research candidate v1','description':'Queue cards are not flight programs. A non-null program requires dated legs and versioned evidence; no unknown numerical values are filled by this schema.','type':'object','required':list(props),'properties':props,'additionalProperties':False,'$defs':{'measure':measure,'program':program,'leg':leg,'product':product}}
    schema['allOf']=[{'if':{'properties':{status:{'const':'UNKNOWN'}}},'then':{'properties':{value:{'type':'null'}}}} for status,value in [('demand_status','demand_value'),('net_fare_status','net_fare_rub'),('resource_status','available_aircraft')]]
    (ROOT/'candidate_schema.json').write_text(json.dumps(schema,ensure_ascii=False,indent=2)+'\n')
    rows=[]
    for line in REQUESTS.splitlines():
        v=line.split('|');assert len(v)==8,v[0]
        r=dict(zip(['data_id','requested_slice','decision_test','join_keys','units','current_limit','candidate_ids','priority_reason'],v))
        r.update(owner_track='core' if int(v[0][1:])<=17 else 'validation' if v[0]=='D30' else 'alternative',request_status='OPEN',collection_boundary='Free public sources only; no messages or purchases',acceptance='Raw+snapshot+SHA256+units+period+coverage; no substitute of proxy for target')
        rows.append(r)
    write_csv(ROOT/'data_requests.csv',rows)
    print(json.dumps({'schema_fields':len(props),'data_requests':len(rows)}))

if __name__=='__main__':main()
